    """Critical impact parameter for a photon on a parabolic orbit.
    b_crit = 3*sqrt(3) * GM / c^2.
    """
    return critical_impact_parameter(M)


def schwarzschild_photon_sphere_radius(M):
    """Photon sphere radius (unstable orbit) r = 3GM/c^2."""
