def bh_entropy(M):
    rs = schwarzschild_radius(M)
    area = 4 * math.pi * rs**2
    return k_B * area * c**3 / (4 * hbar * G)

def main():
    # Example: consider a stellar‑mass black hole (10 M_sun)
    M = 10 * M_sun
    print(f"Schwarzschild radius of {M:.2e} kg: {schwarzschild_radius(M):.3e} m")
    print(f"Hawking temperature: {hawking_temperature(M):.3e} K")
    print(f"Bekenstein‑Hawking entropy: {bh_entropy(M):.3e} J/K")

if __name__ == "__main__":
